namespace App\Http\Controllers\Hrms;

use App\Http\Controllers\Controller;
use App\Models\Payslip;
use Illuminate\Http\Request;

class PayslipController extends Controller
{
    public function show(Request $request, Payslip $payslip)
    {
        if ($payslip->employee_id !== $request->user()->id && !$request->user()->can('managePayroll', Payslip::class)) {
            abort(403, 'Unauthorized access to payslip records.');
        }

        return response()->json([
            'id' => $payslip->id,
            'month' => $payslip->pay_period,
            'gross_salary' => $payslip->gross_amount,
            'net_salary' => $payslip->net_amount,
            'tax_deductions' => $payslip->deductions,
            'bank_account_number' => $payslip->bank_account_last_four
        ]);
    }
}
